-- CineTonight Movie Intelligence — BATCH 1 DRAFTS (1 Sep 2026)
-- Reviewed-by-you is the rule: read every row below, edit any wording you
-- disagree with, then run this in the Supabase SQL editor. Re-running after
-- edits is safe (upsert). Editor is set to 'CineTonight Editorial' — change
-- it if you want your own byline on the Take.
-- Unreleased titles (Avengers: Doomsday) are deliberately absent.

insert into public.movie_intel (id, verdict_headline, watch_if, skip_if, chips, mood, pace, intensity, attention, themes, vibe, expect, best_for_who, best_for_context, best_for_caution, take_title, take_body, alt_id, alt_reasons, episode_rhythm, hook_expectation, editor)
values ('the-odyssey', 'A colossal big-screen epic that rewards patience and full attention.', '["You want a grand, serious spectacle that fills the whole evening", "You loved Oppenheimer''s scale and craft", "Mythology retold with real emotional weight appeals to you"]'::jsonb, '["You want something light or under two hours tonight", "Slow, dialogue-heavy stretches test your patience"]'::jsonb, '["Epic", "Slow build", "Focused"]'::jsonb, 'Awe-inspiring', 'patient', 'moderate', 'focused', '["Homecoming", "Fate and responsibility", "War''s aftermath"]'::jsonb, 'Vast and serious — a myth told with full weight', '[{"label": "Spectacle", "value": "Huge", "level": 3}, {"label": "Emotion", "value": "Strong", "level": 2}, {"label": "Action", "value": "Steady", "level": 2}, {"label": "Humor", "value": "Light", "level": 1}]'::jsonb, 'Anyone who wants cinema at full scale', 'A committed solo or partner watch with the lights off', 'At nearly three hours, not a casual weeknight pick', 'Nolan gives the oldest story real weight', 'The draw here is scale with feeling: the sea, the storms and the homecoming all land with physical force, and the ensemble keeps the myth human. It asks three hours and your full attention, and a few talky stretches drag — but this is the kind of film big screens exist for, and for once the emphatic reception mostly holds.', null, '[]'::jsonb, null, null, 'CineTonight Editorial')
on conflict (id) do update set verdict_headline=excluded.verdict_headline, watch_if=excluded.watch_if, skip_if=excluded.skip_if, chips=excluded.chips, mood=excluded.mood, pace=excluded.pace, intensity=excluded.intensity, attention=excluded.attention, themes=excluded.themes, vibe=excluded.vibe, expect=excluded.expect, best_for_who=excluded.best_for_who, best_for_context=excluded.best_for_context, best_for_caution=excluded.best_for_caution, take_title=excluded.take_title, take_body=excluded.take_body, alt_id=excluded.alt_id, alt_reasons=excluded.alt_reasons, episode_rhythm=excluded.episode_rhythm, hook_expectation=excluded.hook_expectation, editor=excluded.editor, updated_at=now(), reviewed_at=now();

insert into public.movie_intel (id, verdict_headline, watch_if, skip_if, chips, mood, pace, intensity, attention, themes, vibe, expect, best_for_who, best_for_context, best_for_caution, take_title, take_body, alt_id, alt_reasons, episode_rhythm, hook_expectation, editor)
values ('toy-story-5', 'A warm, funny family night that plays safer than Pixar''s best.', '["Family movie night with kids of any age", "You grew up with Woody and Jessie and want one more round", "You want reliable laughs with some real heart"]'::jsonb, '["You''re hoping for Toy Story 3-level emotional depth"]'::jsonb, '["Feel-good", "Family", "Casual"]'::jsonb, 'Warm', 'steady', 'low', 'casual', '["Screens vs play", "Belonging", "Growing up"]'::jsonb, 'Bright, funny and comfortably familiar', '[{"label": "Humor", "value": "High", "level": 3}, {"label": "Emotion", "value": "Present", "level": 2}, {"label": "Action", "value": "Playful", "level": 2}, {"label": "Complexity", "value": "Low", "level": 1}]'::jsonb, 'Families and longtime fans', 'A weekend evening with kids', 'Adults may find its big ideas softened', 'Pixar plays the hits — and mostly gets away with it', 'The tablet-versus-toys premise is a genuinely good hook, Jessie finally gets the spotlight, and the new characters earn their laughs. It raises sharper questions about screens than it is willing to answer, settling for comfort where the best Toy Story films risked heartbreak. As a family night it delivers; as a Pixar milestone it sits a step below the trilogy.', null, '[]'::jsonb, null, null, 'CineTonight Editorial')
